142:   sliceNative(triangles, layerH, mode) {
143:     let minZ = Infinity, maxZ = -Infinity;
144:     for (let i = 2; i < triangles.length; i += 3) {
145:       const z = triangles[i];
146:       if (z < minZ) minZ = z;
147:       if (z > maxZ) maxZ = z;
148:     }
149:     if (!isFinite(minZ) || minZ === maxZ) { minZ = 0; maxZ = 15; }
