        spindleNumber: 1,
        spindleRPM: 12000,
        feedXY: 1400,
        plungeZ: 300,
        stepoverPct: 40,
        passDepth: 1.0,
        changeMode: 'mtc_probe',
        atcSlot: 2,
        notes: 'Fine profiling, small pockets, and precision contour cutouts'
      },
      {
        number: 3,
        name: '1/8" (3.175mm) Tapered Ball Nose Carver (R0.5)',
        type: 'ball',
        diameter: 3.175,
        tipRadius: 0.5,
        fluteLength: 15.0,
        overallLength: 45.0,
        flutes: 2,
        spindleNumber: 2,
        spindleRPM: 18000,
        feedXY: 1600,
        plungeZ: 350,
