303:   renderSlicedStackToVisualizer() {
304:     const app = window.app || window.xe;
305:     if (!app) return;
306: 
307:     // JumpStart attaches Three.js Scene to app.vp.scene
308:     const threeScene = (app.vp && app.vp.scene) || app.scene;
309:     if (!threeScene || !threeScene.add) {
310:       console.warn('[CLE Slicer] Could not locate Three.js scene.');
311:       return;
312:     }
313: 
314:     const THREE = window.THREE || (app.vp && app.vp.THREE) || null;
315:     if (!THREE) return;
316: 
317:     // Clean up previous visualizer group
318:     if (this.visualizerGroup) {
319:       threeScene.remove(this.visualizerGroup);
320:     }
321: 
322:     this.visualizerGroup = new THREE.Group();
323:     this.visualizerGroup.name = 'CLE_Sliced_Toolpath_Stack';
324: 
325:     const numLayers = this.slicedLayers.length;
326:     const isTopDown = (this.mode === 'cnc' || this.mode === 'laser');
327: 
328:     this.slicedLayers.forEach((layer, lIdx) => {
329:       if (layer.points.length < 2) return;
330: 
331:       const positions = [];
332:       const colors = [];
333: 
334:       // Color coding:
335:       // 3D (bottom-up): blue at base -> red at top
336:       // CNC/Laser (top-down): bright green at surface -> deep red at deepest cut
337:       let hue;
338:       if (isTopDown) {
339:         hue = 0.33 - (lIdx / (numLayers || 1)) * 0.33; // 0.33 (green) down to 0.0 (red)
340:       } else {
341:         hue = (lIdx / (numLayers || 1)) * 0.7; // 0.0 to 0.7
342:       }
343:       const color = new THREE.Color().setHSL(Math.max(0, hue), 1.0, 0.55);
344: 
345:       for (let i = 0; i < layer.points.length - 1; i++) {
346:         const p1 = layer.points[i];
347:         const p2 = layer.points[i+1];
348:         positions.push(p1.x, p1.y, p1.z);
349:         positions.push(p2.x, p2.y, p2.z);
350: 
351:         if (p2.isRapid) {
352:           // Rapid traverse in faint cyan/yellow
353:           colors.push(0.3, 0.8, 0.9, 0.3, 0.8, 0.9);
354:         } else {
355:           colors.push(color.r, color.g, color.b, color.r, color.g, color.b);
356:         }
357:       }
358: 
359:       const geom = new THREE.BufferGeometry();
360:       geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
361:       geom.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
362: 
363:       const mat = new THREE.LineBasicMaterial({
364:         vertexColors: true,
365:         linewidth: 2,
366:         transparent: true,
367:         opacity: 0.95
368:       });
369: 
370:       const lineMesh = new THREE.LineSegments(geom, mat);
371:       lineMesh.userData = { layerIndex: lIdx, zElevation: layer.z };
372:       this.visualizerGroup.add(lineMesh);
373:     });
