  if (!found) return;
  localStorage.setItem('cle.vault.active_machine_id', machineId);
  if (found.wifiIP) {
    localStorage.setItem('cle.fluidnc.ip', found.wifiIP);
    if (this.bridge.fluidnc) {
      this.bridge.fluidnc.ip = found.wifiIP;
    }
  }
  if (this.bridge.fluidnc) {
