import subprocess
import time
import json
import urllib.request
import asyncio
import websockets

edge_path = r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"
proc = subprocess.Popen([
    edge_path,
    "--headless=new",
    "--remote-debugging-port=9222",
    "--allow-file-access-from-files",
    r"file:///D:/CLEJS/Dev/index.htm"
], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

time.sleep(2)

async def run():
    try:
        with urllib.request.urlopen("http://127.0.0.1:9222/json/list", timeout=3) as resp:
            targets = json.loads(resp.read().decode())
        js_target = next((t for t in targets if "JumpStart 3D" in t.get("title", "")), None)
        ws_url = js_target["webSocketDebuggerUrl"]
        async with websockets.connect(ws_url) as ws:
            await ws.send(json.dumps({"id": 1, "method": "Runtime.enable"}))
            await asyncio.sleep(1)

            # Connect via CLE.fluidnc using our candidate URL
            expr = """
            new Promise((resolve) => {
                const fnc = window.CLE.fluidnc;
                fnc.socket = new WebSocket('ws://192.168.12.158');
                fnc.socket.binaryType = 'arraybuffer';
                fnc.socket.onopen = () => {
                    fnc.isConnected = true;
                    fnc.connectionType = 'websocket';
                    fnc.startStatusPolling();
                    setTimeout(() => {
                        resolve({
                            connected: fnc.isConnected,
                            state: fnc.state,
                            pos: fnc.pos,
                            wco: fnc.wco
                        });
                    }, 1200);
                };
                fnc.socket.onmessage = (e) => {
                    let d = e.data;
                    if (d instanceof ArrayBuffer) d = new TextDecoder().decode(d);
                    fnc.handleIncomingData(d);
                };
                fnc.socket.onerror = (e) => resolve({ error: 'ws error' });
            })
            """

            await ws.send(json.dumps({
                "id": 50,
                "method": "Runtime.evaluate",
                "params": {"expression": expr, "awaitPromise": True, "returnByValue": True}
            }))

            while True:
                try:
                    msg = await asyncio.wait_for(ws.recv(), timeout=5.0)
                    data = json.loads(msg)
                    if data.get("id") == 50:
                        print("LIVE MACHINE CONNECTION DATA:", data.get("result", {}).get("result", {}).get("value"))
                        break
                except asyncio.TimeoutError:
                    break
    finally:
        proc.terminate()

asyncio.run(run())

