import subprocess
import time
import json
import urllib.request
import asyncio
import websockets

edge_path = r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"
proc = subprocess.Popen([
    edge_path,
    "--headless=new",
    "--remote-debugging-port=9222",
    "--allow-file-access-from-files",
    r"file:///D:/CLEJS/Dev/index.htm"
], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

time.sleep(2)

async def run():
    try:
        with urllib.request.urlopen("http://127.0.0.1:9222/json/list", timeout=3) as resp:
            targets = json.loads(resp.read().decode())
        js_target = next((t for t in targets if "JumpStart 3D" in t.get("title", "")), None)
        ws_url = js_target["webSocketDebuggerUrl"]
        async with websockets.connect(ws_url) as ws:
            await ws.send(json.dumps({"id": 1, "method": "Runtime.enable"}))
            await asyncio.sleep(1)

            expr = """
            (async () => {
                const fnc = window.CLE.fluidnc;

                // Test 1: Connect using ttcwifi.local
                fnc.connectWebSocket('ttcwifi.local');
                await new Promise(r => setTimeout(r, 1200));
                const res1 = {
                    connected: fnc.isConnected,
                    state: fnc.state,
                    ip: fnc.ip,
                    mpos: fnc.mpos
                };
                fnc.disconnect();
                await new Promise(r => setTimeout(r, 300));

                // Test 2: Connect using 192.168.12.158
                fnc.connectWebSocket('192.168.12.158');
                await new Promise(r => setTimeout(r, 1200));
                const res2 = {
                    connected: fnc.isConnected,
                    state: fnc.state,
                    ip: fnc.ip,
                    mpos: fnc.mpos
                };

                return { test_ttcwifi_local: res1, test_ip_158: res2 };
            })()
            """

            await ws.send(json.dumps({
                "id": 60,
                "method": "Runtime.evaluate",
                "params": {"expression": expr, "awaitPromise": True, "returnByValue": True}
            }))

            while True:
                try:
                    msg = await asyncio.wait_for(ws.recv(), timeout=7.0)
                    data = json.loads(msg)
                    if data.get("id") == 60:
                        print("TEST RESULTS FROM LIVE BROWSER:", json.dumps(data.get("result", {}).get("result", {}).get("value"), indent=2))
                        break
                except asyncio.TimeoutError:
                    break
    finally:
        proc.terminate()

asyncio.run(run())

