// Automatically start USB camera if permission was previously granted and device exists
async autoStartIfAvailable() {
  if (this.isActive) return true;
  const isGranted = (this.permissionGranted || localStorage.getItem('cle.cam.permissionGranted') === 'true');
  // Do not pop up camera permission prompt unless user already granted permission once
  if (!isGranted) return false;

  try {
    const devices = await this.getAvailableDevices();
    if (devices && devices.length > 0) {
      const logi = devices.find(d => /logi|c270|webcam/i.test(d.label));
      const devId = logi ? logi.deviceId : (this.selectedDeviceId || devices[0].deviceId);
      return await this.startUSBCamera(devId);
    }
  } catch (e) {
    console.warn('[CLE Camera] Auto-start check error:', e);
  }
  return false;
}

// Enumerate all available USB video inputs on the system
async getAvailableDevices() {
  try {
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return [];
    const devices = await navigator.mediaDevices.enumerateDevices();
    return devices.filter(d => d.kind === 'videoinput');
  } catch (e) {
    console.warn('[CLE Camera] Device enumeration error:', e);
    return [];
  }
}

// Start USB Webcam with auto-selection or selected deviceId
async startUSBCamera(deviceId = this.selectedDeviceId) {
  this.stopCamera();
  try {
    const constraints = {
      video: {
        width: { ideal: 1280 },
        height: { ideal: 720 },
        frameRate: { ideal: 30 }
      }
    };

    if (deviceId) {
      constraints.video.deviceId = { exact: deviceId };
    }

    this.stream = await navigator.mediaDevices.getUserMedia(constraints);
    this.permissionGranted = true;
    this.selectedDeviceId = deviceId;
    localStorage.setItem('cle.cam.deviceId', deviceId);
    localStorage.setItem('cle.cam.permissionGranted', 'true');
    if (this.bridge && this.bridge.vault) {
      this.bridge.vault.saveCameraConfig({
        permissionGranted: true,
        deviceId: deviceId,
        activeType: 'usb'
      });
    }
    this.activeType = 'usb';

