208:   trianglesToSTL(triangles, solidName = 'CLEJS_Model') {
209:     let stl = `solid ${solidName}\n`;
210:     const numTriangles = Math.floor(triangles.length / 9);
211:     for (let i = 0; i < numTriangles; i++) {
212:       const idx = i * 9;
213:       const ax = triangles[idx], ay = triangles[idx+1], az = triangles[idx+2];
214:       const bx = triangles[idx+3], by = triangles[idx+4], bz = triangles[idx+5];
215:       const cx = triangles[idx+6], cy = triangles[idx+7], cz = triangles[idx+8];
216: 
217:       const u1 = bx - ax, u2 = by - ay, u3 = bz - az;
218:       const v1 = cx - ax, v2 = cy - ay, v3 = cz - az;
219:       const nx = u2 * v3 - u3 * v2;
220:       const ny = u3 * v1 - u1 * v3;
221:       const nz = u1 * v2 - u2 * v1;
222:       const len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
223: 
224:       stl += `  facet normal ${nx/len} ${ny/len} ${nz/len}\n`;
225:       stl += '    outer loop\n';
226:       stl += `      vertex ${ax} ${ay} ${az}\n`;
227:       stl += `      vertex ${bx} ${by} ${bz}\n`;
228:       stl += `      vertex ${cx} ${cy} ${cz}\n`;
229:       stl += '    endloop\n';
230:       stl += '  endfacet\n';
231:     }
232:     stl += `endsolid ${solidName}\n`;
233:     return stl;
234:   }
