450:         }
451:         const matchZ = line.match(/Z=([-\d.]+)/i);
452:         const lZ = matchZ ? parseFloat(matchZ[1]) : curZ;
453:         currentLayer = { index: this.slicedLayers.length, z: lZ, points: [], isCutoutPass: true };
