212:   trianglesToSTL(triangles, solidName = 'CLEJS_Model') {
213:     let stl = `solid ${solidName}\n`;
214:     const numTriangles = Math.floor(triangles.length / 9);
215:     for (let i = 0; i < numTriangles; i++) {
216:       const idx = i * 9;
217:       const ax = triangles[idx], ay = triangles[idx+1], az = triangles[idx+2];
218:       const bx = triangles[idx+3], by = triangles[idx+4], bz = triangles[idx+5];
219:       const cx = triangles[idx+6], cy = triangles[idx+7], cz = triangles[idx+8];
220: 
221:       const u1 = bx - ax, u2 = by - ay, u3 = bz - az;
222:       const v1 = cx - ax, v2 = cy - ay, v3 = cz - az;
223:       const nx = u2 * v3 - u3 * v2;
224:       const ny = u3 * v1 - u1 * v3;
225:       const nz = u1 * v2 - u2 * v1;
226:       const len = Math.sqrt(nx*nx + ny*ny + nz*nz) || 1;
227: 
228:       stl += `  facet normal ${nx/len} ${ny/len} ${nz/len}\n`;
229:       stl += '    outer loop\n';
230:       stl += `      vertex ${ax} ${ay} ${az}\n`;
231:       stl += `      vertex ${bx} ${by} ${bz}\n`;
232:       stl += `      vertex ${cx} ${cy} ${cz}\n`;
233:       stl += '    endloop\n';
234:       stl += '  endfacet\n';
235:     }
236:     stl += `endsolid ${solidName}\n`;
237:     return stl;
238:   }
