                color: s.material.color.getHexString()
            });
        }

        return {
            totalMeshes: meshes.length,
            solidCount: solids.length,
            borderCount: borders.length,
            solidDetails: solidDetails,
            currentPreviewLayer: slicer.currentPreviewLayer,
            sliceViewMode: slicer.sliceViewMode
        };
    }''')
    print('GEOMETRY INSPECT:', json.dumps(res, indent=2))
    browser.close()
