    res = page.evaluate('''async () => {
        const THREE = window.THREE;
        const cle = window.CLE;
        const slicer = cle.slicer;
        await slicer.sliceModel({ mode: 'cnc', layerHeight: 1.0 });

        let results = [];
        slicer.slicedLayers.forEach((layer, idx) => {
            const pts = layer.contourPts;
            if (!pts || pts.length < 3) {
                results.push({ layer: idx, err: 'no contour pts' });
                return;
            }
            try {
                const shape = new THREE.Shape();
                shape.moveTo(pts[0].x, pts[0].y);
                for (let k = 1; k < pts.length; k++) shape.lineTo(pts[k].x, pts[k].y);
                shape.closePath();
                const geo = new THREE.ExtrudeGeometry(shape, { depth: 1.0, bevelEnabled: false });
                results.push({ layer: idx, success: true, verts: geo.attributes.position.count });
            } catch (e) {
                results.push({ layer: idx, err: e.message });
            }
        });
        return results.slice(0, 10);
    }''')
    print('SLICE EXTRUDE RESULTS:', json.dumps(res, indent=2))
    browser.close()
"

