import asyncio
from playwright.async_api import async_playwright

async def inspect():
    async with async_playwright() as p:
        browser = await p.chromium.launch(
            headless=True,
            args=["--allow-file-access-from-files", "--disable-web-security"]
        )
        page = await browser.new_page()
        await page.goto("file:///D:/CLEJS/Dev/index.htm")
        await page.wait_for_timeout(3000)

        data = await page.evaluate("""() => {
            const app = window.app || window.xe;
            if (!app) return { error: 'no app' };
            const doc = app.doc || (app.project && app.project.doc);
            const bodies = doc ? doc.bodies : null;
            const scene = app.scene;
            const viewsKeys = scene && scene.views ? Array.from(scene.views.keys()) : [];
            const wsTabs = Array.from(document.querySelectorAll('.wstabs button')).map(b => ({ id: b.id, text: b.textContent }));
            return {
                hasDoc: !!doc,
                bodyCount: bodies ? bodies.length : 0,
                viewsKeys: viewsKeys,
                wsTabs: wsTabs,
                hasAppSetMode: typeof app.setMode,
                hasAppSetWorkspace: typeof app.setWorkspace
            };
        }""")
        print("Inspection result:", data)
        await browser.close()

asyncio.run(inspect())

