115:   // Wraps standard planar G-Code into 4th Axis Rotary G-Code
116:   wrapPlanarGCodeToRotary(gcodeText) {
117:     const lines = gcodeText.split('\n');
118:     const out = [];
119:     out.push(`; --- CLEJS 4th Axis Wrapped (Stock Diameter: ${this.stockDiameter}mm) ---`);
120:     out.push('G90 G21 ; Absolute programming, mm');
121:     out.push('G92 A0 ; Set A0 at start');
122: 
123:     const yPattern = /([Yy])(-?\d+\.?\d*)/;
124: 
125:     for (const line of lines) {
126:       const match = line.match(yPattern);
127:       if (match && !line.startsWith(';')) {
128:         const yVal = parseFloat(match[2]);
129:         const aVal = this.yToRotaryDegrees(yVal).toFixed(3);
130:         const replaced = line.replace(match[0], `A${aVal}`);
131:         out.push(replaced);
132:       } else {
133:         out.push(line);
134:       }
135:     }
136:     return out.join('\n');
137:   }
