args.Content:
import re

# 1. Update Dev/cle_tools/cle_slicer.js
with open('Dev/cle_tools/cle_slicer.js', 'r', encoding='utf-8') as f:
    slicer_content = f.read()

# Remove items 1, 2, 3 (orange box, retract plane, mode plane)
orange_box_pattern = r'      // 1\. Semi-transparent shape outline in transparent orange.*?(?=      // (?:4\.|Center & Frame Visualizer Sphere))'
slicer_content = re.sub(orange_box_pattern, '', slicer_content, flags=re.DOTALL)

# In setWorkspaceBodiesTransparent, remove color forcing to orange and orange edges
slicer_content = slicer_content.replace(
    'if (m.color && m.color.setHex) m.color.setHex(0xf97316); // Vivid Transparent Orange\n',
    '// Keep natural CAD body color with translucent opacity\n'
).replace(
    'if (m.color && m.color.setHex) m.color.setHex(0xf97316); // Vivid Transparent Orange\r\n',
    '// Keep natural CAD body color with translucent opacity\r\n'
)

# Remove orange edge lines generation
old_edges = """      // Orange shape outline edges
      if (transparent && THREE && obj.geometry && !obj._cleEdges) {
        try {
          const edgeGeo = new THREE.EdgesGeometry(obj.geometry);
          const edgeMat = new THREE.LineBasicMaterial({ color: 0xea580c, transparent: true, opacity: 0.65 });
          const edgeLines = new THREE.LineSegments(edgeGeo, edgeMat);
          edgeLines.name = 'CLE_Body_Orange_Edges';
          obj.add(edgeLines);
          obj._cleEdges = edgeLines;
        } catch (e) {}
      } else if (!transparent && obj._cleEdges) {
        obj.remove(obj._cleEdges);
        try { obj._cleEdges.geometry.dispose(); } catch (e) {}
        try { obj._cleEdges.material.dispose(); } catch (e) {}
        delete obj._cleEdges;
      }"""

new_edges = """      // Clear any legacy orange edge outlines if present
      if (obj._cleEdges) {
        obj.remove(obj._cleEdges);
        try { obj._cleEdges.geometry.dispose(); } catch (e) {}
        try { obj._cleEdges.material.dispose(); } catch (e) {}
        delete obj._cleEdges;
      }"""

slicer_content = slicer_content.replace(old_edges.replace('\n', '\r\n'), new_edges.replace('\n', '\r\n'))
slicer_content = slicer_content.replace(old_edges, new_edges)

with open('Dev/cle_tools/cle_slicer.js', 'w', encoding='utf-8') as f:
    f.write(slicer_content)

print("[OK] cle_slicer.js updated: orange box removed.")

