        assert t2_data['hasFloorZ16'] and t2_data['hasPeakZ2'], "Must reference 4mm floor (Z=-16) and 18mm peak (Z=-2)"
        assert t2_data['q1Passes'] >= 100, "Q1 must have 0.1mm Z depth passes"

