    if(s.type==='M') d+=`M ${s.x} ${s.y} `;
    else if(s.type==='L') d+=`L ${s.x} ${s.y} `;
    else if(s.type==='C') d+=`C ${s.x1} ${s.y1} ${s.x2} ${s.y2} ${s.x} ${s.y} `;
  }
  return d.trim();
}
